.avatar {
  position: relative;
  display: inline-grid;
  flex: 0 0 auto;
  place-items: center;
  overflow: visible;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  background: var(--surface-muted);
  color: var(--foreground);
  font-size: var(--text-xs);
  font-weight: 500;
}

.avatar img {
  pointer-events: none;
  border-radius: inherit;
  object-fit: cover;
  transition: opacity var(--duration-standard) var(--ease-enter), filter var(--duration-standard) var(--ease-enter);
}

/* Set only while a photo is still downloading after mount, so cached photos never fade. */
.avatar img[data-loading] {
  opacity: 0;
  filter: blur(4px);
  transition: none;
}

.fallback { animation: avatar-fallback-in var(--duration-standard) var(--ease-enter) both; }

.sm { width: 28px; height: 28px; font-size: 10px; }
.md { width: 36px; height: 36px; }
.lg { width: 48px; height: 48px; font-size: var(--text-sm); }
.xl { width: 88px; height: 88px; font-size: 23px; }

.status {
  position: absolute;
  right: 0;
  bottom: 0;
  z-index: 2;
  width: 10px;
  height: 10px;
  border: 2px solid var(--surface);
  border-radius: var(--radius-pill);
  box-shadow: 0 0 0 1px color-mix(in oklch, var(--border) 70%, transparent);
}

.sm .status { width: 8px; height: 8px; border-width: 1.5px; }
.lg .status { width: 12px; height: 12px; }
.xl .status { width: 14px; height: 14px; right: 4px; bottom: 4px; }
.online { background: var(--success); }
.offline { background: var(--text-muted); }

@keyframes avatar-fallback-in { from { opacity: 0; } to { opacity: 1; } }

@media (prefers-reduced-motion: reduce) {
  .avatar img { transition: none; }
  .avatar img[data-loading] { filter: none; }
  .fallback { animation: none; }
}

.trigger { position: relative; display: grid; width: 42px; height: 42px; place-items: center; border: 1px solid var(--border); border-radius: 12px; background: var(--surface); color: var(--foreground); cursor: pointer; transition: border-color var(--duration-fast) var(--ease-standard), background var(--duration-fast) var(--ease-standard); }
.trigger[data-state="open"], .trigger:active { border-color: var(--border-strong); background: var(--surface-muted); }
@media (hover: hover) and (pointer: fine) { .trigger:hover { border-color: var(--border-strong); background: var(--surface-muted); } }
.trigger > span:first-child { display: grid; place-items: center; }
.badge { position: absolute; top: -6px; right: -6px; display: grid; min-width: 19px; height: 19px; padding: 0 4px; place-items: center; overflow: hidden; border: 2px solid var(--surface); border-radius: 999px; background: var(--foreground); color: var(--background); font-size: 10px; font-weight: 500; font-variant-numeric: tabular-nums; }
.panel { z-index: 90; display: flex; flex-direction: column; width: min(424px, calc(100vw - 24px)); max-height: min(590px, calc(100vh - 24px)); overflow: hidden; border: 1px solid var(--border); border-radius: 23px; background: var(--surface-raised); color: var(--foreground); box-shadow: var(--shadow-floating); font-family: var(--font-body); letter-spacing: var(--tracking-body); transform-origin: var(--radix-popover-content-transform-origin); }
/* The panel grows out of the bell: it starts a few pixels toward the trigger on whichever side Radix placed it, and leaves faster than it arrives. */
.panel { --panel-x: 0px; --panel-y: -6px; }
.panel[data-side="top"] { --panel-y: 6px; }
.panel[data-side="left"] { --panel-x: 6px; --panel-y: 0px; }
.panel[data-side="right"] { --panel-x: -6px; --panel-y: 0px; }
.panel[data-state="open"] { animation: panel-open var(--duration-standard) var(--ease-enter) both; }
.panel[data-state="closed"] { animation: panel-close var(--duration-instant) var(--ease-standard) both; }
.header { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding: 23px 24px 18px; }
.heading { display: flex; align-items: center; gap: 9px; }
.heading h2 { margin: 0; font-size: 20px; font-weight: 500; letter-spacing: -.025em; line-height: 1.2; }
.count { display: grid; min-width: 21px; height: 21px; padding: 0 5px; place-items: center; overflow: hidden; border-radius: 7px; background: var(--surface-muted); color: var(--text-secondary); font-size: 11px; font-variant-numeric: tabular-nums; }
.header p { position: relative; margin: 5px 0 0; color: var(--text-secondary); font-size: 12px; }
.close { display: grid; width: 30px; height: 30px; flex: none; place-items: center; border: 0; border-radius: 8px; background: transparent; color: var(--text-muted); cursor: pointer; transition: transform var(--duration-spring) var(--ease-spring), color var(--duration-fast) var(--ease-standard), background var(--duration-fast) var(--ease-standard); }
.close:active { transform: scale(.96); }
.toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 52px; padding: 0 17px 13px 20px; border-bottom: 1px solid var(--border-subtle); }
.viewSwitch { display: inline-flex; align-items: center; gap: 3px; }
.viewSwitch button { position: relative; isolation: isolate; min-width: 61px; height: 31px; padding: 0 10px; border: 0; border-radius: 9px; background: transparent; color: var(--text-secondary); font: inherit; font-size: 12px; cursor: pointer; transition: color var(--duration-fast) var(--ease-standard); }
.viewSwitch .viewActive { color: var(--foreground); }
.viewSwitch button > span:last-child { position: relative; z-index: 1; }
.viewHighlight { position: absolute; z-index: -1; inset: 0; border-radius: 9px; background: var(--surface-muted); }
.markAll { display: inline-flex; align-items: center; gap: 6px; padding: 6px 0; border: 0; background: transparent; color: var(--text-secondary); font: inherit; font-size: 12px; white-space: nowrap; cursor: pointer; transition: transform var(--duration-spring) var(--ease-spring), color var(--duration-fast) var(--ease-standard); }
.markAll:active { transform: scale(.97); }
.list { min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 9px 11px 10px; scrollbar-width: none; }
.list::-webkit-scrollbar { display: none; }
.row { overflow: hidden; }
/* Rows settle in with a short cascade when the panel opens or a view adds them. */
.item { position: relative; padding: 10px 10px 9px; border-radius: 12px; transition: background var(--duration-fast) var(--ease-standard); animation: item-in var(--duration-standard) var(--ease-enter) calc(var(--index, 0) * 35ms) both; }
.itemExpanded { background: var(--surface-muted); }
.itemRead .itemTitle strong { color: var(--text-secondary); }
.itemMain { display: flex; align-items: flex-start; gap: 11px; min-width: 0; }
.eventIcon { display: grid; width: 24px; height: 36px; flex: none; place-items: center; color: var(--accent); }
.eventIcon.success { color: var(--success); }
.eventIcon.warning { color: var(--warning); }
.itemToggle { display: grid; min-width: 0; flex: 1; gap: 4px; padding: 2px 0 0; border: 0; background: transparent; color: var(--foreground); text-align: left; font: inherit; cursor: pointer; }
.itemTitle { display: flex; align-items: center; gap: 7px; min-width: 0; min-height: 18px; }
.itemTitle strong { overflow: hidden; font-size: 13px; font-weight: 500; line-height: 1.4; text-overflow: ellipsis; white-space: nowrap; }
.unreadDot { display: block; width: 6px; height: 6px; flex: none; border-radius: 50%; background: var(--foreground); }
.itemPreview { overflow: hidden; color: var(--text-secondary); font-size: 12px; line-height: 1.4; text-overflow: ellipsis; white-space: nowrap; }
.time { flex: none; padding-top: 3px; color: var(--text-muted); font-size: 11px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.details { overflow: hidden; padding-left: 47px; }
.details p { margin: 11px 0 13px; color: var(--text-secondary); font-size: 12px; line-height: 1.55; }
.itemActions { display: flex; flex-wrap: wrap; gap: 6px; padding-bottom: 5px; }
.itemActions button { display: inline-flex; align-items: center; gap: 5px; min-height: 29px; padding: 4px 8px; overflow: clip; border: 1px solid var(--border); border-radius: 8px; background: transparent; color: var(--foreground); font: inherit; font-size: 11px; white-space: nowrap; cursor: pointer; transition: transform var(--duration-spring) var(--ease-spring), border-color var(--duration-fast) var(--ease-standard), background var(--duration-fast) var(--ease-standard); }
.itemActions button:active { transform: scale(.97); }
/* Quick press, spring release: the resting transition above carries the spring back. */
.close:active, .markAll:active, .itemActions button:active, .footer button:active { transition-duration: var(--duration-instant); transition-timing-function: var(--ease-standard); }
.morph { display: block; }
.morphContent { position: relative; display: inline-flex; width: max-content; align-items: center; gap: 5px; }
.actionIcon, .actionGlyph { position: relative; display: grid; place-items: center; }
.swap { position: relative; display: inline-block; max-width: 100%; vertical-align: top; }
.swapLine { display: block; }
.roll { position: relative; display: inline-grid; vertical-align: top; }
.rollValue { display: block; }
.emptyFrame { overflow: hidden; }
.empty { display: grid; justify-items: center; align-content: center; min-height: 190px; padding: 22px 12px; text-align: center; }
.empty > svg { margin-bottom: 13px; color: var(--text-muted); }
.empty strong { font-size: 14px; font-weight: 500; }
.empty p { margin: 4px 0 0; color: var(--text-secondary); font-size: 12px; }
.empty button { margin-top: 16px; padding: 0; border: 0; background: transparent; color: var(--foreground); font: inherit; font-size: 12px; text-decoration: underline; text-underline-offset: 3px; cursor: pointer; }
.footerFrame { flex: none; overflow: hidden; }
.footer { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 46px; padding: 8px 22px; border-top: 1px solid var(--border-subtle); color: var(--text-muted); font-size: 11px; }
.footer button { padding: 4px 0; border: 0; background: transparent; color: var(--text-secondary); font: inherit; font-size: 11px; cursor: pointer; transition: transform var(--duration-spring) var(--ease-spring), color var(--duration-fast) var(--ease-standard); }
.footer button:active { transform: scale(.97); }
@media (hover: hover) and (pointer: fine) {
  .close:hover, .item:hover { background: var(--surface-muted); }
  .close:hover, .viewSwitch button:hover, .markAll:hover, .footer button:hover { color: var(--foreground); }
  .itemActions button:hover { border-color: var(--border-strong); background: var(--surface); }
}
.trigger:focus-visible, .close:focus-visible, .viewSwitch button:focus-visible, .markAll:focus-visible, .itemToggle:focus-visible, .itemActions button:focus-visible, .empty button:focus-visible, .footer button:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
@keyframes panel-open { from { opacity: 0; transform: translate(var(--panel-x), var(--panel-y)) scale(.97); } }
@keyframes panel-close { to { opacity: 0; transform: translate(calc(var(--panel-x) / 2), calc(var(--panel-y) / 2)) scale(.98); } }
@keyframes item-in { from { opacity: 0; transform: translateY(4px); } }
@media (max-width: 380px) { .header { padding: 20px 16px 16px; } .heading h2 { font-size: 18px; } .toolbar { align-items: flex-start; padding: 0 12px 12px; } .list { padding: 8px 5px; } .item { padding-inline: 7px; } .itemMain { gap: 7px; } .time { padding-top: 4px; font-size: 10px; } .details { padding-left: 31px; } .itemActions { gap: 5px; } .itemActions button { padding-inline: 7px; } .markAll span { display: none; } .footer { padding-inline: 16px; } }
@media (prefers-reduced-motion: reduce) { .panel[data-state], .trigger, .close, .viewSwitch button, .markAll, .item, .itemActions button, .footer button { animation: none; transition-duration: 0ms; } .close:active, .markAll:active, .itemActions button:active, .footer button:active { transform: none; } }
